import * as THREE from 'three'

// ---------------------------------------------------------------------------
// MALHAS 3D ESCULPIDAS E SUBDIVIDIDAS NO BLENDER (CATMULL-CLARK SUBSURF)
//
// Gerado diretamente a partir do depsgraph avaliado do Blender 5.2 LTS
// (`public/modelos/hubbia_sims_studio.blend` e `hubbia_sims_studio.glb`).
// Cada malha possui topologia quad contínua subdividida com Catmull-Clark:
//   - `cabeca`: cabeça + pescoço + nariz + órbitas + maçãs + queixo + orelhas
//   - `torso_camisa_unificado` e `bracos_maos_unificados`: tronco, ombros,
//     mangas, antebraços, mãos e polegares fundidos sem costura
//   - `calca_unificada`: cintura, quadril, glúteos, coxas, joelhos e canelas
//     em malha única ramificada 100% manifold
//   - `cabelo_*`: os 7 cortes de cabelo estilizados subdivididos
//   - `calcado_*`, `planta_*`, `cafeteira_*`, `cadeira_*`, `sofa_*`, `banheira_*`
// ---------------------------------------------------------------------------

