export type ChaveMalhaBlender = keyof typeof MALHAS_BLENDER

const CACHE_GEOMETRIAS = new Map<ChaveMalhaBlender, THREE.BufferGeometry>()

function decodificarBytesBase64(b64: string): Uint8Array {
  const bin = atob(b64)
  const len = bin.length
  const bytes = new Uint8Array(len)
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i)
  }
  return bytes
}

export function obterGeometriaBlender(chave: ChaveMalhaBlender): THREE.BufferGeometry {
  const emCache = CACHE_GEOMETRIAS.get(chave)
  if (emCache) return emCache.clone()

  const dados = MALHAS_BLENDER[chave]
  const vBytes = decodificarBytesBase64(dados.v)
  const iBytes = decodificarBytesBase64(dados.i)

  const int16 = new Int16Array(vBytes.buffer, vBytes.byteOffset, vBytes.byteLength / 2)
  const uint16 = new Uint16Array(iBytes.buffer, iBytes.byteOffset, iBytes.byteLength / 2)

  const posicoes = new Float32Array(int16.length)
  for (let i = 0; i < int16.length; i++) {
    posicoes[i] = int16[i] / 10000.0
  }

  const geo = new THREE.BufferGeometry()
  geo.setAttribute('position', new THREE.BufferAttribute(posicoes, 3))
  geo.setIndex(new THREE.BufferAttribute(uint16, 1))
  geo.computeVertexNormals()

  const numVertices = posicoes.length / 3;
  const uvs = new Float32Array(numVertices * 2);
  for (let i = 0; i < numVertices; i++) {
    const x = posicoes[i * 3];
    const y = posicoes[i * 3 + 1];
    const z = posicoes[i * 3 + 2];
    uvs[i * 2] = 0.5 + Math.atan2(z, x) / (2 * Math.PI);
    uvs[i * 2 + 1] = y * 2 + 0.5;
  }
  geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));

  CACHE_GEOMETRIAS.set(chave, geo);
  return geo.clone();
}

export type ChaveSubmalhaBlender =
  | 'calca_pelve'
  | 'calca_coxa_esq'
  | 'calca_coxa_dir'
  | 'calca_panturrilha_esq'
  | 'calca_panturrilha_dir'
  | 'braco_ombro_esq'
  | 'braco_ombro_dir'
  | 'braco_antebraco_esq'
  | 'braco_antebraco_dir'
  | 'braco_mao_esq'
  | 'braco_mao_dir'
  | 'torso_peito';

const CACHE_SUBMALHAS = new Map<string, THREE.BufferGeometry>();

export function obterSubmalhaBlender(chave: ChaveSubmalhaBlender): THREE.BufferGeometry {
  const emCache = CACHE_SUBMALHAS.get(chave);
  if (emCache) return emCache.clone();

  let geo: THREE.BufferGeometry;

  if (chave === 'torso_peito') {
    const base = obterGeometriaBlender('torso_camisa_unificado');
    const pos = base.attributes.position;
    const count = pos.count;
    const novosV = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      novosV[i * 3] = pos.getX(i);
      novosV[i * 3 + 1] = pos.getY(i) - 0.64;
      novosV[i * 3 + 2] = pos.getZ(i);
    }
    geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(novosV, 3));
    geo.setIndex(base.index!.clone());
    geo.computeVertexNormals();

    const uvs = new Float32Array(count * 2);
    for (let i = 0; i < count; i++) {
      const x = novosV[i * 3];
      const y = novosV[i * 3 + 1];
      const z = novosV[i * 3 + 2];
      uvs[i * 2] = 0.5 + Math.atan2(z, x) / (2 * Math.PI);
      uvs[i * 2 + 1] = y * 2 + 0.5;
    }
    geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));

    CACHE_SUBMALHAS.set(chave, geo);
    return geo.clone();
  }

  let chavePai: 'calca_unificada' | 'bracos_maos_unificados' = 'calca_unificada';
  let filtro: (x: number, y: number) => boolean = () => true;
  let offset = [0, 0, 0];

  switch (chave) {
    case 'calca_pelve':
      chavePai = 'calca_unificada';
      filtro = (_x, y) => y >= 0.49;
      offset = [0, 0.56, 0];
      break;
    case 'calca_coxa_esq':
      chavePai = 'calca_unificada';
      filtro = (x, y) => y < 0.49 && y >= 0.255 && x < 0;
      offset = [-0.082, 0.525, 0];
      break;
    case 'calca_coxa_dir':
      chavePai = 'calca_unificada';
      filtro = (x, y) => y < 0.49 && y >= 0.255 && x > 0;
      offset = [0.082, 0.525, 0];
      break;
    case 'calca_panturrilha_esq':
      chavePai = 'calca_unificada';
      filtro = (x, y) => y < 0.255 && x < 0;
      offset = [-0.082, 0.273, 0];
      break;
    case 'calca_panturrilha_dir':
      chavePai = 'calca_unificada';
      filtro = (x, y) => y < 0.255 && x > 0;
      offset = [0.082, 0.273, 0];
      break;
    case 'braco_ombro_esq':
      chavePai = 'bracos_maos_unificados';
      filtro = (x, y) => y >= 0.77 && x < 0;
      offset = [-0.186, 0.965, 0];
      break;
    case 'braco_ombro_dir':
      chavePai = 'bracos_maos_unificados';
      filtro = (x, y) => y >= 0.77 && x > 0;
      offset = [0.186, 0.965, 0];
      break;
    case 'braco_antebraco_esq':
      chavePai = 'bracos_maos_unificados';
      filtro = (x, y) => y < 0.77 && y >= 0.58 && x < 0;
      offset = [-0.186, 0.773, 0];
      break;
    case 'braco_antebraco_dir':
      chavePai = 'bracos_maos_unificados';
      filtro = (x, y) => y < 0.77 && y >= 0.58 && x > 0;
      offset = [0.186, 0.773, 0];
      break;
    case 'braco_mao_esq':
      chavePai = 'bracos_maos_unificados';
      filtro = (x, y) => y < 0.58 && x < 0;
      offset = [-0.186, 0.585, 0];
      break;
    case 'braco_mao_dir':
      chavePai = 'bracos_maos_unificados';
      filtro = (x, y) => y < 0.58 && x > 0;
      offset = [0.186, 0.585, 0];
      break;
  }

  const dados = MALHAS_BLENDER[chavePai];
  const vBytes = decodificarBytesBase64(dados.v);
  const iBytes = decodificarBytesBase64(dados.i);
  const int16 = new Int16Array(vBytes.buffer, vBytes.byteOffset, vBytes.byteLength / 2);
  const uint16 = new Uint16Array(iBytes.buffer, iBytes.byteOffset, iBytes.byteLength / 2);

  const mapaV = new Map<number, number>();
  const novosV: number[] = [];
  const novosI: number[] = [];

  function obterOuCriar(antigoIdx: number): number {
    const emMapa = mapaV.get(antigoIdx);
    if (emMapa !== undefined) return emMapa;
    const novoIdx = novosV.length / 3;
    const x = int16[antigoIdx * 3] / 10000.0 - offset[0];
    const y = int16[antigoIdx * 3 + 1] / 10000.0 - offset[1];
    const z = int16[antigoIdx * 3 + 2] / 10000.0 - offset[2];
    novosV.push(x, y, z);
    mapaV.set(antigoIdx, novoIdx);
    return novoIdx;
  }

  for (let t = 0; t < uint16.length; t += 3) {
    const a = uint16[t];
    const b = uint16[t + 1];
    const c = uint16[t + 2];
    const ya = int16[a * 3 + 1] / 10000.0;
    const yb = int16[b * 3 + 1] / 10000.0;
    const yc = int16[c * 3 + 1] / 10000.0;
    const xa = int16[a * 3] / 10000.0;
    const xb = int16[b * 3] / 10000.0;
    const xc = int16[c * 3] / 10000.0;
    const medY = (ya + yb + yc) / 3;
    const medX = (xa + xb + xc) / 3;
    if (filtro(medX, medY)) {
      novosI.push(obterOuCriar(a), obterOuCriar(b), obterOuCriar(c));
    }
  }

  geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(novosV), 3));
  geo.setIndex(new THREE.BufferAttribute(new Uint16Array(novosI), 1));
  geo.computeVertexNormals();

  const countSub = novosV.length / 3;
  const uvs = new Float32Array(countSub * 2);
  for (let i = 0; i < countSub; i++) {
    const x = novosV[i * 3];
    const y = novosV[i * 3 + 1];
    const z = novosV[i * 3 + 2];
    uvs[i * 2] = 0.5 + Math.atan2(z, x) / (2 * Math.PI);
    uvs[i * 2 + 1] = y * 2 + 0.5;
  }
  geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));

  CACHE_SUBMALHAS.set(chave, geo);
  return geo.clone();
}

